1=1 AND c.case_type=#{filter.caseType}
    AND c.case_status=#{filter.caseStatus}
    AND (LOCATE(#{filter.keyword},c.title)>0 OR c.case_no=#{filter.keyword})

mapper.select:
SELECT c.case_type,c.case_status,c.version,r.relation_type AS source_type,r.relation_id AS source_id,
  COALESCE(c.buyer_user_id,o.buyer_user_id) AS beneficiary
 LEFT JOIN rental_order o ON o.id=c.rental_order_id WHERE c.id=#{id}

choose.otherwise:
 WITH source_orders AS (
SELECT id AS order_id FROM rental_order WHERE id=#{source.sourceId}
SELECT id AS order_id FROM custom_order WHERE id=#{source.sourceId}
SELECT id AS order_id FROM custom_order WHERE accepted_quote_id=#{source.sourceId}
SELECT id AS order_id FROM custom_order WHERE requirement_id=#{source.sourceId}
SELECT custom_order_id AS order_id FROM custom_after_sale_request WHERE id=#{source.sourceId}
SELECT id AS order_id FROM rental_order WHERE payment_order_id=#{source.sourceId} UNION ALL SELECT id FROM custom_order WHERE payment_order_id=#{source.sourceId}
SELECT COALESCE(rental_order_id,biz_order_id) AS order_id FROM refund_order WHERE id=#{source.sourceId}
SELECT rental_order_id AS order_id FROM order_issue_report WHERE id=#{source.sourceId}
SELECT rental_order_id AS order_id FROM order_extension_request WHERE id=#{source.sourceId}
SELECT rental_order_id AS order_id FROM order_return_check WHERE id=#{source.sourceId}
SELECT rental_order_id AS order_id FROM order_transport_leg WHERE id=#{source.sourceId}
SELECT rental_order_id AS order_id FROM order_compensation_receivable WHERE id=#{source.sourceId}
SELECT rental_order_id AS order_id FROM order_claim WHERE id=#{source.sourceId}
SELECT rental_order_id AS order_id FROM arbitration_case WHERE id=#{source.sourceId}
SELECT rental_order_id AS order_id FROM arbitration_decision WHERE id=#{source.sourceId}
SELECT NULL AS order_id WHERE FALSE
), evidence AS (
SELECT id AS order_id FROM rental_order WHERE id=#{ref.sourceId}
SELECT id AS order_id FROM custom_order WHERE id=#{ref.sourceId}
SELECT rental_order_id AS order_id FROM order_issue_report WHERE id=#{ref.sourceId}
SELECT rental_order_id AS order_id FROM order_claim WHERE id=#{ref.sourceId}
SELECT rental_order_id AS order_id FROM arbitration_decision WHERE id=#{ref.sourceId} AND decision_status='confirmed'
SELECT COALESCE(rental_order_id,biz_order_id) AS order_id FROM refund_order WHERE id=#{ref.sourceId} AND refund_status='success'
SELECT custom_order_id AS order_id FROM custom_after_sale_request WHERE id=#{ref.sourceId}
SELECT NULL AS order_id WHERE FALSE
)
 SELECT EXISTS(SELECT 1 FROM evidence e LEFT JOIN rental_order r ON r.id=e.order_id LEFT JOIN custom_order c ON c.id=e.order_id
 LEFT JOIN factory_profile f ON f.id=COALESCE(r.factory_id,c.factory_id)
 WHERE (COALESCE(r.buyer_user_id,c.buyer_user_id)=#{user} OR f.owner_user_id=#{user})
 AND (#{source.sourceType}='sys_user' OR EXISTS(SELECT 1 FROM source_orders s WHERE s.order_id=e.order_id)))
